avancado.solucao:
-- Antes
SELECT regiao, SUM(valor) FROM vendas GROUP BY regiao HAVING regiao = 'SUL';
-- Depois: filtra linhas antes de agregar
SELECT regiao, SUM(valor) FROM vendas WHERE regiao = 'SUL' GROUP BY regiao;
-- No plano, o otimizador costuma empurrar o filtro do HAVING para antes do Aggregate,
-- mas escrever no WHERE deixa a intenção explícita e não depende dessa otimização.

-- NOT IN (2, NULL) vira id <> 2 AND id <> NULL -> desconhecido para todas as linhas.
SELECT c.*
FROM clientes AS c
WHERE NOT EXISTS (
    SELECT 1 FROM bloqueados AS b WHERE b.id_cliente = c.id_cliente
);

